     var finalizeAllLookUpTcsTransacaoMenu = function (replaceTo, selectedElements, propertyName, lookupInfo) {
        if (!replaceTo || !selectedElements)
            return;
        if (!Array.isArray(selectedElements)) {
            selectedElements = [selectedElements];
        }
        var originalRow = replaceTo;
        var hasDisconsideredElement = false;
        var parent = getAbsoluteValue(replaceTo.TcsModuloMenu);
        isFinalizingLookup(true);
        if (!propertyName)
            propertyName = '';
        var isUsedOriginalRow = false;
        for (var i = 0; i < selectedElements.length; i++)
        {
            var selectedElement = selectedElements[i];
            var isInvalidElement = false;
            var curList = parent.TcsTransacaoMenuList();
            for (var idx = 0; idx < curList.length; idx++) {
               if (curList[idx] != originalRow && getAbsoluteValue(curList[idx].IdTransacao) === getAbsoluteValue(selectedElement['IdTransacao'])) {
                   isInvalidElement = true;
                   hasDisconsideredElement = true;
                   break;
               }
            }
            if (isInvalidElement) continue;
            if (isUsedOriginalRow) {
                replaceTo = lookupInfo.vm.createTcsTransacaoMenu(parent);
            }
            else {
                isUsedOriginalRow = true;
            }
            if (propertyName === '' || propertyName === 'IdTransacao') {
               if (selectedElement.hasOwnProperty('IdTransacao') && replaceTo.hasOwnProperty('IdTransacao'))
               {
                   setAbsoluteValue(replaceTo, 'IdTransacao', getAbsoluteValue(selectedElement['IdTransacao']));
               }
               else if (replaceTo.hasOwnProperty('IdTransacao')) {
                   setAbsoluteValue(replaceTo, 'IdTransacao', 0);
               }
            }
            if (propertyName === '' || propertyName === 'DescTransacao') {
               if (selectedElement.hasOwnProperty('DescTransacao') && replaceTo.hasOwnProperty('DescTransacao'))
               {
                   setAbsoluteValue(replaceTo, 'DescTransacao', getAbsoluteValue(selectedElement['DescTransacao']));
               }
               else if (replaceTo.hasOwnProperty('DescTransacao')) {
                   setAbsoluteValue(replaceTo, 'DescTransacao', '');
               }
            }
            if (replaceTo.validatedlookupsArray && !replaceTo.validatedlookupsArray.contains('LookUpTcsTransacaoMenu'))
                replaceTo.validatedlookupsArray.push('LookUpTcsTransacaoMenu');
        }
        //Trigger context data update event
        if (replaceTo.isPOCO) vm.refreshCurrentBind();
        document.dispatchEvent(dataUpdateEvent);
        isFinalizingLookup(false);
        if (hasDisconsideredElement) {
           clearLookUpTcsTransacaoMenu(replaceTo);
           app.showMessage('Itens que já estão sendo utilizados foram desconsiderados nessa seleção!', 'Informação', ['Ok']);
        }
    };
    
