    var createAppMenu = function() {
        //Create entity instance
        enableChangeTrack = false;
        var entity = createEntity('AppMenu', { Id: (-1 * getSequence('AppMenu')), IdTcsAmbiente: (-1 * getSequence('AppMenu')), IsTransaction: false, IsFavorite: false });
        entity.setDefaults();
        if (typeof entity.OnAdding == 'function') {
            if (!entity.OnAdding()) { dataContext.deleteEntity(entity); return; }
        }
        enableChangeTrack = true;
        return entity;
    };
    
